import{_ as i,o as a,c as e,a6 as l}from"./chunks/framework.C1YrMf1e.js";const r="/Art_web_public/assets/image-2.DsNEY-8U.png",o="/Art_web_public/assets/image.C7HrHgd-.png",s="/Art_web_public/assets/image-1.Dt6INbtV.png",n="/Art_web_public/assets/image-3.DRPNTkkZ.png",u="/Art_web_public/assets/image-4.jYX-RSqQ.png",c="/Art_web_public/assets/image-5.BzFT5mvl.png",p="/Art_web_public/assets/image-6.CoKeyh1Q.png",d="/Art_web_public/assets/image-7.fuHImTDl.png",K=JSON.parse('{"title":"KTT","description":"","frontmatter":{"readingTime":"4 min read"},"headers":[],"relativePath":"全流程美术/Houdini/KTT/KTT.md","filePath":"全流程美术/Houdini/KTT/KTT.md"}'),h={name:"全流程美术/Houdini/KTT/KTT.md"};function _(T,t,m,g,b,f){return a(),e("div",null,[...t[0]||(t[0]=[l('<h1 id="ktt" tabindex="-1">KTT <a class="header-anchor" href="#ktt" aria-label="Permalink to &quot;KTT&quot;">​</a></h1><p><img src="'+r+'" alt="alt text"><br> KTT(Kruger Terrain Tools) 是适用于 Houdini 20.5 + 的地形生成工具集，与Houdini原生高度场工具兼容，可接入现有项目，可快速生成高质量地形数据。 革新了 Houdini 地形制作流程，兼具软件灵活性与高度场建模创新功能，支持多系统且提供永久授权。<br><a href="https://samk9632.gumroad.com/l/KTTforHoudini" target="_blank" rel="noreferrer">KTT for Houdini</a></p><h3 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to &quot;核心功能&quot;">​</a></h3><ol><li>含50+自定义地形处理节点，覆盖从初始形状搭建、细节优化、纹理制作到可视化与导出的全流程。</li><li>具备GPU加速侵蚀模拟、全流程精准控制、分辨率无关模拟（实时调整分辨率不改变外观）。</li><li>高效处理高分辨率地形（最高支持16k×16k及以上），支持Windows、Linux、MacOS系统。</li><li>每个节点均配备文档和示例，提供永久授权，无需续费或付费更新。</li></ol><h3 id="安装与入门" tabindex="-1">安装与入门 <a class="header-anchor" href="#安装与入门" aria-label="Permalink to &quot;安装与入门&quot;">​</a></h3><ul><li>需Houdini 20.5及以上版本（建议20.5.641+）拷贝所有文件到C:\\Users\\xjw\\Documents\\houdini21.0\\packages下（无此文件夹可新建）。</li><li>入门步骤：新建Geometry节点并进入，在节点编辑器右键找到“Kruger Terrain Tools”子菜单，添加“KTT Handbook”节点，按手册“入门”和“工作流”章节操作即可制作首个地形。<br><img src="'+o+'" alt="alt text"></li></ul><h2 id="ktt-基础" tabindex="-1">KTT 基础 <a class="header-anchor" href="#ktt-基础" aria-label="Permalink to &quot;KTT 基础&quot;">​</a></h2><p>KTT 工具集以houdini内置的 heightfield 为基础来制作。<br> heightfield 是一种二维体积数据，只有高度维度，而不是点线面数据。</p><h3 id="heightfield" tabindex="-1">heightfield <a class="header-anchor" href="#heightfield" aria-label="Permalink to &quot;heightfield&quot;">​</a></h3><p><img src="'+s+'" alt="alt text"></p><ul><li>Grid Spacing：网格间距，影响地形精度。<br> 和地形size大小一起影响地形精度。一般Size不会高频变动。 可以在信息窗口查看分辨率。<br> 一般来说精度和运行解算速度有关系。必要时候会在一些节点做缓存节点。</li></ul><h2 id="ktt-mountain" tabindex="-1">KTT_Mountain <a class="header-anchor" href="#ktt-mountain" aria-label="Permalink to &quot;KTT_Mountain&quot;">​</a></h2><p><img src="'+n+'" alt="alt text"></p><ul><li>Combine Method 合并模式，一般是覆盖。也可以看需求add</li><li>seed 随机种子</li><li>Mountain Sieze 山体大小</li><li>Mountain height 山体高度</li><li>Mountain height Ramp 山体曲线定义</li><li>Transforms 山体的平移旋转。但也可以使用单独的<strong>KTT_Transform</strong>来实现</li><li>Stretching 拉伸</li></ul><p><img src="'+u+'" alt="alt text"></p><blockquote><p>Noise Displacement 噪波。地形的细节特征</p></blockquote><ul><li><strong>Fractal</strong> 是基础噪波上叠加的次级噪波，可以在叠加后做出很丰富的层次</li><li><strong>Max Octaves</strong> 叠加的次数。叠加越多细节越丰富</li><li><strong>Lacunarity</strong> 不需要改动，是一个比较理想的值</li><li><strong>Roughness</strong> 数值越小越平滑，反之越粗糙</li></ul><p><img src="'+c+'" alt="alt text"></p><ul><li>LatticeWarp 扭曲强度</li><li>Freq 扭曲频率</li></ul><p><img src="'+p+'" alt="alt text"></p><ul><li>输出数据调整。用得不是很多</li></ul><hr><p><img src="'+d+'" alt="alt text"></p><blockquote><p>Noise Distortion 扭曲。可以打破山体边缘圆形的形状，使山体边缘变化更多样化。</p></blockquote>',24)])])}const x=i(h,[["render",_]]);export{K as __pageData,x as default};
